-- =====================================================================
-- V2 系统表基线 · 登录支撑表 + 种子数据
--
-- 为什么需要这个文件：
--   V1 只建了 PoC 三表（t_employee / t_menu / t_dict + t_dict_data），
--   V2 只建了登录 RBAC 关联表。但 SmartAdmin 的登录链路还依赖：
--     t_config        -> ConfigService.getConfigValue(SUPER_PASSWORD) 与三级等保配置
--     t_login_log     -> LoginLogService.log / queryLastByUserId
--     t_login_fail    -> SecurityLoginService.checkLogin / recordLoginFail
--     t_password_log  -> SecurityPasswordService.checkNeedChangePassword
--   缺任意一张都会在登录或登录后取用户信息时抛 SQL 异常。
--
-- 转换规则见 V1 文件头（identity / BOOLEAN / TIMESTAMP / 命名约束）。
--
-- 种子数据来源：SmartAdmin v3.31 官方 MySQL 脚本，已转换：
--   - 菜单树保留系统/运维/监控/文档/代码生成等全部条目
--   - 排除 ERP 商品 Demo 子树（47/48/78/79），其 Vue 视图在 V2 已删除
--   - 部门/职务/员工/角色改为 V2 自建最小集（不引入官方演示账号）
-- =====================================================================

-- ---------------------------------------------------------------------
-- t_config 系统配置
-- ---------------------------------------------------------------------
CREATE TABLE t_config (
    config_id    BIGINT       GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    config_name  VARCHAR(255) NOT NULL,
    config_key   VARCHAR(255) NOT NULL,
    config_value TEXT         NOT NULL,
    remark       VARCHAR(255),
    update_time  TIMESTAMP    NOT NULL DEFAULT CURRENT_TIMESTAMP,
    create_time  TIMESTAMP    NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT uk_t_config_key UNIQUE (config_key)
);

COMMENT ON TABLE t_config IS '系统配置';
COMMENT ON COLUMN t_config.config_name IS '参数名字';
COMMENT ON COLUMN t_config.config_key IS '参数key';
COMMENT ON COLUMN t_config.config_value IS '参数值';

-- ---------------------------------------------------------------------
-- t_login_log 用户登录日志
-- ---------------------------------------------------------------------
CREATE TABLE t_login_log (
    login_log_id    BIGINT        GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    user_id         INTEGER       NOT NULL,
    user_type       INTEGER       NOT NULL,
    user_name       VARCHAR(1000) NOT NULL,
    login_ip        VARCHAR(1000),
    login_ip_region VARCHAR(1000),
    user_agent      TEXT,
    login_device    VARCHAR(1000),
    login_result    INTEGER       NOT NULL,
    remark          VARCHAR(2000),
    update_time     TIMESTAMP     NOT NULL DEFAULT CURRENT_TIMESTAMP,
    create_time     TIMESTAMP     NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE INDEX idx_t_login_log_user_id ON t_login_log (user_id);

COMMENT ON TABLE t_login_log IS '用户登录日志';
COMMENT ON COLUMN t_login_log.login_result IS '登录结果：0成功 1失败 2退出';

-- ---------------------------------------------------------------------
-- t_login_fail 登录失败次数记录
-- ---------------------------------------------------------------------
CREATE TABLE t_login_fail (
    login_fail_id           BIGINT        GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    user_id                 BIGINT        NOT NULL,
    user_type               INTEGER       NOT NULL,
    login_name              VARCHAR(1000),
    login_fail_count        INTEGER,
    lock_flag               BOOLEAN       DEFAULT FALSE,
    login_lock_begin_time   TIMESTAMP,
    create_time             TIMESTAMP     NOT NULL DEFAULT CURRENT_TIMESTAMP,
    update_time             TIMESTAMP     NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT uk_t_login_fail_user UNIQUE (user_id, user_type)
);

COMMENT ON TABLE t_login_fail IS '登录失败次数记录表';
COMMENT ON COLUMN t_login_fail.lock_flag IS '锁定状态:true锁定，false未锁定';

-- ---------------------------------------------------------------------
-- t_password_log 密码修改记录
-- ---------------------------------------------------------------------
CREATE TABLE t_password_log (
    id           BIGINT       GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    user_id      BIGINT       NOT NULL,
    user_type    SMALLINT     NOT NULL,
    old_password VARCHAR(255) NOT NULL,
    new_password VARCHAR(255),
    update_time  TIMESTAMP    NOT NULL DEFAULT CURRENT_TIMESTAMP,
    create_time  TIMESTAMP    NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE INDEX idx_t_password_log_user ON t_password_log (user_id, user_type);

COMMENT ON TABLE t_password_log IS '密码修改记录';

