-- =====================================================================
-- 序列校正
-- 使用显式 ID 插入后，identity 序列不会自动前进；
-- 不校正会导致后续 insert 主键冲突。pg_get_serial_sequence 同时支持
-- identity 列与 serial 列。
-- =====================================================================
SELECT setval(pg_get_serial_sequence('t_config', 'config_id'),        (SELECT MAX(config_id)        FROM t_config));
SELECT setval(pg_get_serial_sequence('t_department', 'department_id'),(SELECT MAX(department_id)    FROM t_department));
SELECT setval(pg_get_serial_sequence('t_position', 'position_id'),    (SELECT MAX(position_id)      FROM t_position));
SELECT setval(pg_get_serial_sequence('t_employee', 'employee_id'),    (SELECT MAX(employee_id)      FROM t_employee));
SELECT setval(pg_get_serial_sequence('t_role', 'role_id'),            (SELECT MAX(role_id)          FROM t_role));
SELECT setval(pg_get_serial_sequence('t_menu', 'menu_id'),            (SELECT MAX(menu_id)          FROM t_menu));
SELECT setval(pg_get_serial_sequence('t_dict', 'dict_id'),            (SELECT MAX(dict_id)          FROM t_dict));
SELECT setval(pg_get_serial_sequence('t_dict_data', 'dict_data_id'),  (SELECT MAX(dict_data_id)     FROM t_dict_data));

